import { LineChart, type LineChartSeriesToggleDetail } from '@absoluteui/components/line-chart';
import { plainDate, plainDateTime, toInstant } from '@absoluteui/core';

const months = Array.from({ length: 6 }, (_, i) => toInstant(plainDateTime(plainDate(2026, i + 1, 1)), 'Europe/London'));
const host = document.createElement('div');
document.body.append(host);
const chart = LineChart.create(host, {
  label: 'Monthly active users',
  description: 'Thousands of users',
  x: months,
  series: [
    { id: 'web', label: 'Web', values: [42, 45, null, 51, 55, 61] },
    { id: 'mobile', label: 'Mobile', values: [30, 33, 38, 41, 47, 52] },
  ],
  yAxis: { label: 'Users (thousands)' },
  timezone: 'Europe/London',
});
host.addEventListener('aui-series-toggle', (event) => {
  const { hidden } = (event as CustomEvent<LineChartSeriesToggleDetail>).detail;
  host.dataset.hidden = hidden.join(',');
});
chart.update({ hiddenSeries: ['mobile'] });

import { LineChart } from '@absoluteui/components/line-chart';

const host = document.querySelector<HTMLElement>('#cash');
if (host) {
  LineChart.create(host, {
    label: 'Net cash flow',
    x: ['Q1', 'Q2', 'Q3', 'Q4'],
    series: [{ id: 'cash', label: 'Cash flow', values: [-120, 40, 180, 95] }],
    area: true,
    height: 220,
    valueFormat: { style: 'currency', currency: 'USD', maximumFractionDigits: 0 },
    dataTable: 'visible',
  });
}

import { LineChart, type LineChartZoomDetail } from '@absoluteui/components/line-chart';

const days = Array.from({ length: 60 }, (_, i) => i + 1);
const host = document.createElement('div');
document.body.append(host);
const chart = LineChart.create(host, {
  label: 'Daily orders',
  x: days,
  series: [{ id: 'orders', label: 'Orders', values: days.map((d) => 100 + ((d * 17) % 40)) }],
  xAxis: { label: 'Day' },
  zoom: true,
  zoomRange: { from: 1, to: 14 },
  crosshair: true,
});
host.addEventListener('aui-zoom', (event) => {
  const { x, reason } = (event as CustomEvent<LineChartZoomDetail>).detail;
  host.dataset.window = x ? `${String(x.from)}-${String(x.to)} (${reason})` : 'all';
});
chart.update({ zoomRange: null });
